## Herencia prototípica manual

Antes de las clases ES6, la herencia se implementaba a mano conectando prototipos de funciones constructoras. Entender esto te explica QUÉ hacen `class` y `extends` bajo el capó.

---

## Funciones constructoras

Cuando llamas una función con `new`, JavaScript:
1. Crea un nuevo objeto
2. Le asigna como `[[Prototype]]` el `.prototype` de la función
3. Ejecuta la función con `this` apuntando al nuevo objeto
4. Retorna el objeto

```javascript
function Animal(nombre, sonido) {
  this.nombre = nombre;
  this.sonido = sonido;
}

// Los métodos van en el PROTOTIPO (compartidos entre instancias)
Animal.prototype.hablar = function () {
  return `${this.nombre} dice ${this.sonido}`;
};

const gato = new Animal('Michi', 'miau');
const perro = new Animal('Rex', 'guau');

console.log(gato.hablar()); // 'Michi dice miau'
console.log(perro.hablar()); // 'Rex dice guau'

// El método es compartido — UNA sola copia
console.log(gato.hablar === perro.hablar); // true
```

---

## Implementar herencia entre constructoras

Para que `Perro` herede de `Animal`, necesitas dos pasos:

**Paso 1:** Llamar al constructor padre desde el hijo (herencia de datos)
**Paso 2:** Conectar los prototipos (herencia de métodos)

```javascript
function Animal(nombre) {
  this.nombre = nombre;
}
Animal.prototype.respirar = function () {
  return `${this.nombre} respira`;
};

// ─── Herencia ────────────────────────────────────────────────────────────────

function Perro(nombre, raza) {
  Animal.call(this, nombre); // Paso 1: hereda datos
  this.raza = raza;
}

// Paso 2: hereda métodos
Perro.prototype = Object.create(Animal.prototype);
Perro.prototype.constructor = Perro; // Reparar constructor

Perro.prototype.ladrar = function () {
  return `${this.nombre} (${this.raza}) dice guau`;
};

const rex = new Perro('Rex', 'Labrador');
console.log(rex.respirar()); // 'Rex respira' — heredado
console.log(rex.ladrar());   // 'Rex (Labrador) dice guau' — propio
console.log(rex instanceof Perro);  // true
console.log(rex instanceof Animal); // true
```

---

## ¿Por qué reparar el constructor?

```javascript
function Animal(nombre) { this.nombre = nombre; }
function Perro(nombre) { Animal.call(this, nombre); }

// Sin reparar:
Perro.prototype = Object.create(Animal.prototype);
console.log(new Perro('Rex').constructor === Animal); // true ← INCORRECTO

// Con reparación:
Perro.prototype.constructor = Perro;
console.log(new Perro('Rex').constructor === Perro); // true ← CORRECTO
```

---

## Cadena completa: 3 niveles

```javascript
// Nivel 1
function Ser() {}
Ser.prototype.existir = () => 'existo';

// Nivel 2
function Animal(nombre) {
  Ser.call(this);
  this.nombre = nombre;
}
Animal.prototype = Object.create(Ser.prototype);
Animal.prototype.constructor = Animal;
Animal.prototype.moverse = function () {
  return `${this.nombre} se mueve`;
};

// Nivel 3
function Perro(nombre, raza) {
  Animal.call(this, nombre);
  this.raza = raza;
}
Perro.prototype = Object.create(Animal.prototype);
Perro.prototype.constructor = Perro;
Perro.prototype.ladrar = function () {
  return 'guau';
};

const rex = new Perro('Rex', 'Labrador');
console.log(rex.existir()); // 'existo' — de Ser
console.log(rex.moverse()); // 'Rex se mueve' — de Animal
console.log(rex.ladrar());  // 'guau' — de Perro
```

---

## Equivalencia con clases ES6

Esto es exactamente lo que hace `class` / `extends` internamente:

```javascript
// Clases ES6 — azúcar sintáctica sobre prototipos
class Animal {
  constructor(nombre) { this.nombre = nombre; }
  respirar() { return `${this.nombre} respira`; }
}

class Perro extends Animal {
  constructor(nombre, raza) {
    super(nombre); // = Animal.call(this, nombre)
    this.raza = raza;
  }
  ladrar() { return 'guau'; }
}

// El resultado a nivel de prototipos es IDÉNTICO al manual
```

examples.code:
// Verificar la cadena de prototipos manualmente
function Vehiculo(marca) { this.marca = marca; }
Vehiculo.prototype.tipo = 'vehiculo';

function Coche(marca, modelo) {
  Vehiculo.call(this, marca);
  this.modelo = modelo;
}
Coche.prototype = Object.create(Vehiculo.prototype);
Coche.prototype.constructor = Coche;

const c = new Coche('Toyota', 'Corolla');

// Verificaciones de la cadena
console.log(c instanceof Coche);    // true
console.log(c instanceof Vehiculo); // true
console.log(c.tipo);                // 'vehiculo' (heredado)
console.log(Object.getPrototypeOf(c) === Coche.prototype); // true
console.log(Object.getPrototypeOf(Coche.prototype) === Vehiculo.prototype); // true

// Llamar al método del padre (super manual)
function Forma(color) { this.color = color; }
Forma.prototype.describir = function () {
  return `Forma de color ${this.color}`;
};

function Circulo(color, radio) {
  Forma.call(this, color);
  this.radio = radio;
}
Circulo.prototype = Object.create(Forma.prototype);
Circulo.prototype.constructor = Circulo;

Circulo.prototype.describir = function () {
  // Llamar al método del padre (equivalente a super.describir())
  const base = Forma.prototype.describir.call(this);
  return `${base}, radio ${this.radio}`;
};

const c = new Circulo('rojo', 5);
console.log(c.describir()); // 'Forma de color rojo, radio 5'

